import{_ as e,o as s,c as o,a5 as i}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse('{"title":"setTimeout 排期与可能的问题","description":"宏任务 ：setTimeout(fn, delay) 注册的是一个宏任务（Task），放在 “定时器” 阶段执行。 4 ms 最小间隔 ：现代浏览器会把所有小于 4 ms 的 delay 都 clamp 到 4 ms；如果当前页面在后台，很多浏览器会进一步 throttle 到。","frontmatter":{"title":"setTimeout 排期与可能的问题","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","工程化、质量与性能"],"description":"宏任务 ：setTimeout(fn, delay) 注册的是一个宏任务（Task），放在 “定时器” 阶段执行。 4 ms 最小间隔 ：现代浏览器会把所有小于 4 ms 的 delay 都 clamp 到 4 ms；如果当前页面在后台，很多浏览器会进一步 throttle 到。","sidebarWeight":54,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/性能优化/深度面试：浏览器中与任务执行、渲染和事件循环/setTimeout 排期与可能的问题.md"},"headers":[],"relativePath":"posts/Vue系统教程/06-工程化、质量与性能/深度面试：浏览器中与任务执行、渲染和事件循环/setTimeout 排期与可能的问题.md","filePath":"posts/Vue系统教程/06-工程化、质量与性能/深度面试：浏览器中与任务执行、渲染和事件循环/setTimeout 排期与可能的问题.md"}'),l={name:"posts/Vue系统教程/06-工程化、质量与性能/深度面试：浏览器中与任务执行、渲染和事件循环/setTimeout 排期与可能的问题.md"};function r(a,t,n,m,u,d){return s(),o("div",null,[...t[0]||(t[0]=[i('<div><h1 id="settimeout-排期与可能的问题" tabindex="-1">setTimeout 排期与可能的问题 <a class="header-anchor" href="#settimeout-排期与可能的问题" aria-label="Permalink to &quot;setTimeout 排期与可能的问题&quot;">​</a></h1><blockquote><p>本节目标：理解“setTimeout 排期与可能的问题”的核心思路，并能把它用于实际开发或面试表达。</p></blockquote><ul><li><strong>宏任务</strong>：setTimeout(fn, delay) 注册的是一个宏任务（Task），放在 “定时器” 阶段执行。</li><li><strong>4 ms 最小间隔</strong>：现代浏览器会把所有小于 4 ms 的 delay 都 clamp 到 4 ms；如果当前页面在后台，很多浏览器会进一步 throttle 到 1000 ms 以上。</li><li><strong>与重绘不同步</strong>：虽然 HTML 规范保证“定时器阶段”发生在绘制前，但<strong>不会与每帧精确对齐</strong>；如果你的回调需跟动画/UI 同步，就会产生“卡帧”或“抖动”。</li><li><strong>漂移 (drift)</strong>：如果回调内部执行时间较长，下次定时器的实际触发会被推迟；不断累加就会导致节奏变慢。</li><li><strong>后台节流</strong>：在不可视标签页或最小化窗口时，浏览器通常会大幅降低定时器的调用频率，甚至暂停调用，导致数据和 UI 更新严重滞后。</li></ul><p><strong>可能的问题</strong></p><ol><li><strong>更新抖动</strong>：回调与浏览器每 16.7 ms 一次的重绘不同步，视觉上不连贯。</li><li><strong>累积延迟</strong>：长业务逻辑占用时间会让后续定时器回调不断后移，无法保持稳定频率。</li><li><strong>不可控的抑制</strong>：在后台或能耗模式下，定时器可能被完全暂停，实时性丢失。</li></ol><p><strong>小结</strong></p><ul><li>若追求与浏览器重绘 <strong>精确对齐</strong>，且需要可控频率，推荐用 useRafFn＋节流逻辑。</li><li>若只是做低频次的非动画更新（比如几百毫秒一次），setTimeout 也能胜任，但要注意浏览器 clamp/drift/后台节流带来的不稳定性。</li></ul></div>',1)])])}const p=e(l,[["render",r]]);export{g as __pageData,p as default};
